-     private CoreOp.FuncOp getFuncOp(String name) {
-        Optional<Method> om = Stream.of(this.getClass().getDeclaredMethods())
-                .filter(m -> m.getName().equals(name))
-                .findFirst();
-
-        Method m = om.get();
